insert into public.templates (
  id, slug, name, description, category_id, template_type, thumbnail_url, preview_url,
  is_premium, config_schema, default_content, default_colors, default_typography,
  animation_config, sort_order
)
values
  ('22222222-2222-4222-8222-222222222240', 'friendship-playlist', 'Our Kind of Chaos', 'A bright, photo-ready friendship card for the friend who feels like home.', '11111111-1111-4111-8111-111111111106', 'friendship', '/api/template-art/friendship-playlist', '/api/template-art/friendship-playlist', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"You Make Life More Fun","message":"For every laugh until we cried, every voice note that should have been a phone call, and every time you just knew what I needed. I am glad it is you.","theme":{"background":"#FFF7EB","accent":"#D37B4E","secondary":"#F4DFC5","text":"#33271F"},"animation":{"type":"sparkles","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#FFF7EB","accent":"#D37B4E","secondary":"#F4DFC5","text":"#33271F"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"sparkles","intensity":"low"}'::jsonb, 160),
  ('22222222-2222-4222-8222-222222222241', 'appreciation-sunshine', 'A Little More Light', 'A sunlit thank-you for someone whose kindness changes the whole day.', '11111111-1111-4111-8111-111111111107', 'appreciation', '/api/template-art/appreciation-sunshine', '/api/template-art/appreciation-sunshine', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"You Make Things Brighter","message":"You probably do not realise how much the small things matter. The check-ins, the kindness, the way you show up. I notice. Thank you.","theme":{"background":"#FFF9E9","accent":"#C58A36","secondary":"#F3E7BD","text":"#30291F"},"animation":{"type":"sparkles","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#FFF9E9","accent":"#C58A36","secondary":"#F3E7BD","text":"#30291F"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"sparkles","intensity":"low"}'::jsonb, 165),
  ('22222222-2222-4222-8222-222222222242', 'dinner-date-candlelight', 'Candlelight Invitation', 'A warm, elegant invitation with a little anticipation and all the dinner details.', '11111111-1111-4111-8111-111111111104', 'dinner_date', '/api/template-art/dinner-date-candlelight', '/api/template-art/dinner-date-candlelight', true, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"An Evening, Just Us","message":"Keep Thursday evening free. I have a table in mind, a playlist ready, and a very good reason to get dressed up. Will you come?","theme":{"background":"#281F28","accent":"#E2AA68","secondary":"#493547","text":"#FFF6E9"},"animation":{"type":"candles","intensity":"medium"},"music":{"enabled":true,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#281F28","accent":"#E2AA68","secondary":"#493547","text":"#FFF6E9"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"candles","intensity":"medium"}'::jsonb, 170),
  ('22222222-2222-4222-8222-222222222243', 'beach-date-golden-hour', 'Golden Hour by the Sea', 'A sunset beach invitation with soft waves and space to make a plan together.', '11111111-1111-4111-8111-111111111105', 'beach_date', '/api/template-art/beach-date-golden-hour', '/api/template-art/beach-date-golden-hour', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"Meet Me at the Water","message":"Let us leave the week behind for a little while. Bare feet, something cold to drink, and the sky doing that thing it does just before the sun goes down.","theme":{"background":"#FFF2E6","accent":"#D47856","secondary":"#F3D4BA","text":"#372622"},"animation":{"type":"waves","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#FFF2E6","accent":"#D47856","secondary":"#F3D4BA","text":"#372622"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"waves","intensity":"low"}'::jsonb, 175),
  ('22222222-2222-4222-8222-222222222244', 'anniversary-our-story', 'The Story So Far', 'A keepsake anniversary design for all the little moments that became your story.', '11111111-1111-4111-8111-111111111103', 'anniversary', '/api/template-art/anniversary-our-story', '/api/template-art/anniversary-our-story', true, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"Still My Favourite Story","message":"From the ordinary Tuesdays to the days we will tell forever, I would choose this story again. Thank you for every chapter so far.","theme":{"background":"#FBF4EA","accent":"#AF745C","secondary":"#EBDDCC","text":"#312722"},"animation":{"type":"petals","intensity":"medium"},"music":{"enabled":true,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#FBF4EA","accent":"#AF745C","secondary":"#EBDDCC","text":"#312722"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"petals","intensity":"medium"}'::jsonb, 180),
  ('22222222-2222-4222-8222-222222222245', 'celebration-new-chapter', 'A New Chapter', 'A thoughtful congratulations card for fresh starts, big moves, and brave decisions.', '11111111-1111-4111-8111-111111111111', 'celebration', '/api/template-art/celebration-new-chapter', '/api/template-art/celebration-new-chapter', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"Here Is to What Comes Next","message":"You worked for this, you hoped for this, and now here you are. Take a moment to feel proud before the next adventure starts.","theme":{"background":"#F4F7EE","accent":"#738C65","secondary":"#DFE8D5","text":"#293126"},"animation":{"type":"float","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#F4F7EE","accent":"#738C65","secondary":"#DFE8D5","text":"#293126"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"float","intensity":"low"}'::jsonb, 185),
  ('22222222-2222-4222-8222-222222222246', 'question-forever', 'A Question from the Heart', 'An intimate, gently animated proposal page for a once-in-a-lifetime question.', '11111111-1111-4111-8111-111111111109', 'question', '/api/template-art/question-forever', '/api/template-art/question-forever', true, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"Will You Choose Me?","message":"I do not need a perfect answer or a perfect moment. I just want to keep choosing life with you. Will you marry me?","theme":{"background":"#28202A","accent":"#E5B974","secondary":"#493548","text":"#FFF8ED"},"animation":{"type":"stars","intensity":"medium"},"music":{"enabled":true,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#28202A","accent":"#E5B974","secondary":"#493548","text":"#FFF8ED"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"stars","intensity":"medium"}'::jsonb, 190),
  ('22222222-2222-4222-8222-222222222247', 'custom-photo-keepsake', 'The Little Things', 'A soft, open canvas for a personal photo, a small story, and words worth keeping.', '11111111-1111-4111-8111-111111111112', 'custom', '/api/template-art/custom-photo-keepsake', '/api/template-art/custom-photo-keepsake', false, '{"sections":["basics","design","media","experience"]}'::jsonb, '{"title":"A Few Things I Love","message":"The way you laugh before you finish the story. The way you remember the details. The way this ordinary day feels better with you in it.","theme":{"background":"#F6F2EA","accent":"#9D7860","secondary":"#E8DFD2","text":"#302923"},"animation":{"type":"fade","intensity":"low"},"music":{"enabled":false,"track":"dreamy"},"media":[]}'::jsonb, '{"background":"#F6F2EA","accent":"#9D7860","secondary":"#E8DFD2","text":"#302923"}'::jsonb, '{"heading":"playfair","body":"inter"}'::jsonb, '{"type":"fade","intensity":"low"}'::jsonb, 195)
on conflict do nothing;
